function Test-CustomAppProductionPostApplyStageCleanupArtifactV010 {
    param([Parameter(Mandatory=$true)]$PreparedResult,[Parameter(Mandatory=$true)]$StageExecutorResult,[Parameter(Mandatory=$true)][string]$Name)
    $root=Get-CustomAppProductionPostApplyCommitCleanupCanonicalPathV010 (Get-CustomAppStageWorkspaceRootV010);$workspace=Get-CustomAppProductionPostApplyCommitCleanupCanonicalPathV010 ([string]$PreparedResult.stage_workspace_path)
