    if(-not (Test-Path -LiteralPath $workspace)){return [pscustomobject]@{ok=$true;reason='stage-workspace-already-absent';status='already-absent';path=$workspace;root=$root}}
    try{$rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop;$workspaceItem=Get-Item -LiteralPath $workspace -Force -ErrorAction Stop;if(($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or ($workspaceItem.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or -not $workspaceItem.PSIsContainer){return [pscustomobject]@{ok=$false;reason='stage-workspace-unsafe-root-or-target'}};$children=@(Get-ChildItem -LiteralPath $workspace -Force -ErrorAction Stop);$bad=@($children|Where-Object{[string]$_.Name -notin @('stage','remote.zip')});if($bad.Count -gt 0){return [pscustomobject]@{ok=$false;reason='stage-workspace-unexpected-entry'}};$stageChild=@($children|Where-Object{[string]$_.Name -ceq 'stage'});if($stageChild.Count -ne 1 -or -not $stageChild[0].PSIsContainer -or ($stageChild[0].Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){return [pscustomobject]@{ok=$false;reason='stage-workspace-stage-entry-invalid'}};$stage=Get-CustomAppLocalRuntimeBaseline -Name $Name -AppPath $stageChild[0].FullName;if(-not [bool]$stage.safe -or -not [bool]$stage.installable -or [string]$stage.tree_sha256 -cne [string]$StageExecutorResult.remote_tree_sha256){return [pscustomobject]@{ok=$false;reason='stage-workspace-runtime-drift'}};$zip=@($children|Where-Object{[string]$_.Name -ceq 'remote.zip'});if($zip.Count -gt 1){return [pscustomobject]@{ok=$false;reason='stage-workspace-remote-zip-ambiguous'}};if($zip.Count -eq 1){if($zip[0].PSIsContainer -or ($zip[0].Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){return [pscustomobject]@{ok=$false;reason='stage-workspace-remote-zip-unsafe'}};$zipHash=(Get-FileHash -LiteralPath $zip[0].FullName -Algorithm SHA256).Hash.ToLowerInvariant();if($zipHash -cne ([string]$StageExecutorResult.archive_sha256).Trim().ToLowerInvariant()){return [pscustomobject]@{ok=$false;reason='stage-workspace-remote-zip-hash-mismatch'}}}}
    catch{return [pscustomobject]@{ok=$false;reason=('stage-workspace-read-failed:'+[string]$_.Exception.Message)}}
    return [pscustomobject]@{ok=$true;reason='stage-workspace-present-and-exact';status='present-verified';path=$workspace;root=$root}
