function Remove-CustomAppProductionPostApplyBoundedArtifactV010 {
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$ExpectedRoot,[Parameter(Mandatory=$true)][string]$ExpectedNamePattern,[Parameter(Mandatory=$true)][string]$Label)
    $root=Get-CustomAppProductionPostApplyCommitCleanupCanonicalPathV010 $ExpectedRoot;$target=Get-CustomAppProductionPostApplyCommitCleanupCanonicalPathV010 $Path
    if(-not ([IO.Path]::GetDirectoryName($target)).Equals($root,[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetFileName($target) -notmatch $ExpectedNamePattern){throw "$Label bounded path check failed"}
    if(-not (Test-Path -LiteralPath $target)){return 'already-absent'}
    $rootItem=Get-Item -LiteralPath $root -Force -ErrorAction Stop;$item=Get-Item -LiteralPath $target -Force -ErrorAction Stop
    if(($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0 -or -not $item.PSIsContainer){throw "$Label root or target is unsafe"}
    [IO.Directory]::Delete($target,$true)
    if(Test-Path -LiteralPath $target){throw "$Label remained after delete"}
    return 'deleted-now'
}

