function Test-CustomAppProductionPostApplyCommitCleanupResultV010 {
    param([AllowNull()]$Result)
    if($null -eq $Result){return [pscustomobject]@{ok=$false;reason='cleanup-result-null'}}
    $required=@('schema','managed_by','qualified_apply_executor_head','status','reason','name','consumption_id','apply_result_fingerprint','live_tree_sha256','remote_tree_sha256','remote_commit_sha','binding_fingerprint','persistence_fingerprint','stage_cleanup_status','app_backup_cleanup_status','persistence_backup_cleanup_status','cleanup_completed_at','update_commit_complete','all_transaction_artifacts_clean','requires_new_permit_for_future_update','cleanup_fingerprint','result_is_authority','spicetify_apply_authorized','additional_mutation_authorized','production_execution_authorized','production_mutation_authorized')
    foreach($field in $required){if(-not $Result.PSObject.Properties[$field]){return [pscustomobject]@{ok=$false;reason=('cleanup-result-required-field-missing-'+$field)}}}
    if([int]$Result.schema -ne $CustomAppProductionPostApplyCommitCleanupSchema -or [string]$Result.managed_by -cne $CustomAppProductionPostApplyCommitCleanupManagedBy -or [string]$Result.qualified_apply_executor_head -cne $CustomAppProductionPostApplyCommitCleanupQualifiedApplyExecutorHead -or [string]$Result.status -cne 'post-apply-transaction-committed-artifacts-clean' -or [string]$Result.reason -cne 'applied-state-reverified-and-bounded-transaction-artifacts-cleaned'){return [pscustomobject]@{ok=$false;reason='cleanup-result-owner-schema-parent-status-or-reason-invalid'}}
    if(-not [bool]$Result.update_commit_complete -or -not [bool]$Result.all_transaction_artifacts_clean -or -not [bool]$Result.requires_new_permit_for_future_update){return [pscustomobject]@{ok=$false;reason='cleanup-result-completion-contract-invalid'}}
    foreach($field in @('result_is_authority','spicetify_apply_authorized','additional_mutation_authorized','production_execution_authorized','production_mutation_authorized')){if([bool]$Result.$field){return [pscustomobject]@{ok=$false;reason=('cleanup-result-'+$field+'-true')}}}
    foreach($field in @('consumption_id','apply_result_fingerprint','live_tree_sha256','remote_tree_sha256','binding_fingerprint','persistence_fingerprint','cleanup_fingerprint')){if(-not (Test-CustomAppProductionPostApplyCommitCleanupSha256V010 (([string]$Result.$field).Trim().ToLowerInvariant()))){return [pscustomobject]@{ok=$false;reason=('cleanup-result-invalid-'+$field)}}}
    if(([string]$Result.remote_commit_sha).Trim().ToLowerInvariant() -notmatch '^[0-9a-f]{40}$'){return [pscustomobject]@{ok=$false;reason='cleanup-result-remote-commit-invalid'}}
    foreach($field in @('stage_cleanup_status','app_backup_cleanup_status','persistence_backup_cleanup_status')){if([string]$Result.$field -notin @('deleted-now','already-absent')){return [pscustomobject]@{ok=$false;reason=('cleanup-result-invalid-'+$field)}}}
    $at=[DateTimeOffset]::MinValue;if(-not [DateTimeOffset]::TryParse([string]$Result.cleanup_completed_at,[ref]$at)){return [pscustomobject]@{ok=$false;reason='cleanup-result-time-invalid'}}
    $expected=Get-CustomAppProductionPostApplyCommitCleanupSha256V010 (Get-CustomAppProductionPostApplyCommitCleanupResultMaterialV010 $Result);if(([string]$Result.cleanup_fingerprint).Trim().ToLowerInvariant() -cne $expected){return [pscustomobject]@{ok=$false;reason='cleanup-result-fingerprint-mismatch'}}
    return [pscustomobject]@{ok=$true;reason='cleanup-result-valid-non-authoritative';cleanup_fingerprint=$expected}
}

